function compute(s) {
  const Q = s.Q, K = s.K, V = s.V;
  const nq = Q.length, dk = Q[0].length, nk = K.length, dv = V[0].length;
  const scaleOn = !!s.scale;
  const denom = scaleOn ? Math.sqrt(dk) : 1;
  const S = [];
  for (let i = 0; i < nq; i++) {
    const row = [];
    for (let j = 0; j < nk; j++) {
      let dot = 0;
      for (let c = 0; c < dk; c++) dot += Q[i][c] * K[j][c];
      row.push(dot);
    }
    S.push(row);
  }
  const Z = S.map(r => r.map(v => v / denom));
  const A = Z.map(row => {
    const m = Math.max(...row);
    const ex = row.map(v => Math.exp(v - m));
    const sum = ex.reduce((a, b) => a + b, 0);
    return ex.map(e => e / sum);
  });
  const O = [];
  for (let i = 0; i < nq; i++) {
    const row = [];
    for (let c = 0; c < dv; c++) {
      let acc = 0;
      for (let j = 0; j < nk; j++) acc += A[i][j] * V[j][c];
      row.push(acc);
    }
    O.push(row);
  }
  const rowSums = A.map(r => r.reduce((a, b) => a + b, 0));
  const maxAbsErr = Math.max(...rowSums.map(s => Math.abs(s - 1)));
  const scoreVar = dk;
  const metrics = [
    {label: 'd_k', value: dk, unit: 'components'},
    {label: 'd_v', value: dv, unit: 'components'},
    {label: 'Max |row sum - 1|', value: maxAbsErr, unit: ''},
    {label: 'Score variance (theory)', value: scoreVar, unit: ''},
    {label: 'Scaling factor', value: denom, unit: ''}
  ];
  const steps = [
    {label: 'Raw scores S = Q K^T', formula: 'S[i][j] = sum_c Q[i][c] K[j][c]', value: JSON.stringify(S), explanation: 'Each entry is the dot product of query i with key j.'},
    {label: 'Scaled scores Z = S / sqrt(d_k)', formula: 'Z = S / ' + denom.toFixed(4), value: JSON.stringify(Z.map(r => r.map(v => Number(v.toFixed(4))))), explanation: scaleOn ? 'Scaling keeps score magnitudes near unit variance when components are independent with unit variance.' : 'Scaling is off, so raw dot products feed softmax directly.'},
    {label: 'Weights A = softmax(Z) row-wise', formula: 'A[i][j] = exp(Z[i][j]) / sum_k exp(Z[i][k])', value: JSON.stringify(A.map(r => r.map(v => Number(v.toFixed(4))))), explanation: 'Softmax turns each row of scores into a probability distribution over keys.'},
    {label: 'Output O = A V', formula: 'O[i][c] = sum_j A[i][j] V[j][c]', value: JSON.stringify(O.map(r => r.map(v => Number(v.toFixed(4))))), explanation: 'Each output row is the attention-weighted average of the value rows.'}
  ];
  const panels = [
    {kind: 'matrix', title: 'Raw scores S = Q K^T', description: 'Dot products before scaling.', rows: Q.map((_, i) => 'q' + i), columns: K.map((_, j) => 'k' + j), values: S},
    {kind: 'matrix', title: 'Scaled scores Z', description: scaleOn ? 'S divided by sqrt(d_k).' : 'Scaling is off, so Z equals S.', rows: Q.map((_, i) => 'q' + i), columns: K.map((_, j) => 'k' + j), values: Z},
    {kind: 'matrix', title: 'Attention weights A', description: 'Softmax applied across each row; every row sums to 1.', rows: Q.map((_, i) => 'q' + i), columns: K.map((_, j) => 'k' + j), values: A},
    {kind: 'matrix', title: 'Output O = A V', description: 'Weighted combinations of value rows.', rows: Q.map((_, i) => 'q' + i), columns: V[0].map((_, c) => 'v' + c), values: O},
    {kind: 'bar', title: 'Row sums of A', description: 'Each bar should be 1 for a valid softmax row.', labels: Q.map((_, i) => 'row ' + i), values: rowSums, unit: ''}
  ];
  const message = 'Each weight row sums to ' + rowSums.map(s => s.toFixed(4)).join(', ') + '. The output rows are the corresponding weighted sums of V rows. ' + (scaleOn ? 'Scaling by 1/sqrt(d_k) keeps scores from exploding as d_k grows.' : 'Without scaling, large dot products can make softmax nearly one-hot.');
  return {metrics, panels, steps, message};
}
